// Mantém somente números em telefones e IDs
const somenteNumeros = valor =>
  String(valor ?? '').replace(/\D/g, '');

// Transforma uma tabela do Sheets em objetos
function transformarTabela(values = []) {
  const [cabecalho = [], ...linhas] = values;

  return linhas.map((linha, indice) => {
    const campos = cabecalho
      .map((coluna, posicao) => [
        String(coluna ?? '').trim(),
        linha[posicao] ?? '',
      ])
      .filter(([coluna]) => coluna);

    return Object.fromEntries([
      ['row_number', indice + 2],
      ...campos,
    ]);
  });
}

// Resposta do CONSULTA_BD_ADMIN
const valueRanges =
  $input.first().json.valueRanges;

if (!Array.isArray(valueRanges)) {
  throw new Error(
    'CONSULTA_BD_ADMIN não retornou valueRanges.'
  );
}

// Localiza uma aba dentro do resultado
function buscarAba(nome) {
  const bloco = valueRanges.find(item =>
    String(item.range || '')
      .replaceAll("'", '')
      .startsWith(`${nome}!`)
  );

  return transformarTabela(bloco?.values);
}

// Administrador que enviou a mensagem
const adminPhone = somenteNumeros(
  $('payload_webhook').first().json.phone
);

if (!adminPhone) {
  throw new Error(
    'Telefone do administrador não encontrado.'
  );
}

// Procura a sessão do administrador
const sessao = buscarAba('admin_sessions')
  .find(item =>
    somenteNumeros(item.admin_phone) === adminPhone
  ) || {};

// Carrega e normaliza todos os usuários
const usuarios = buscarAba('user_profile')
  .filter(item => somenteNumeros(item.user_id))
  .map(item => ({
    ...item,

    user_id:
      somenteNumeros(item.user_id),

    // Vazio também significa VITA ligada
    vita_status:
      String(item.vita_status || 'on')
        .trim()
        .toLowerCase() || 'on',
  }));

// Um único item para continuar o workflow
return [
  {
    json: {
      admin_phone: adminPhone,

      session_row_number:
        sessao.row_number || null,

      etapa:
        String(sessao.etapa || 'menu').trim() ||
        'menu',

      acao:
        String(sessao.acao || '').trim(),

      updated_at:
  String(sessao.updated_at || '').trim(),

      pagina:
        Math.max(
          1,
          Number(sessao.pagina) || 1
        ),

      lista_json:
        sessao.lista_json || '',

      usuario_selecionado_json:
  sessao.usuario_selecionado_json || '',

      usuarios,
    },
  },
];

