  (() => {
    const porPagina = 8;

    const pagina = Number(
      $json.usuarios_filtrados[0].pagina || 1
    );

    const inicio = (pagina - 1) * porPagina;

    const usuariosPagina = $json.usuarios_filtrados.slice(
      inicio,
      inicio + porPagina
    );

    const totalPaginas = Math.max(
      1,
      Math.ceil(
        $json.usuarios_filtrados.length / porPagina
      )
    );

    const temMais =
      $json.usuarios_filtrados.length >
      inicio + porPagina;

    const titulo =
      $json.usuarios_filtrados[0].acao === 'desligar'
        ? '*USUÁRIOS PARA DESLIGAR*'
        : '*USUÁRIOS PARA REATIVAR*';

    const mascararTelefone = valor => {
      const numero = String(valor || '')
        .replace(/\D/g, '');

      if (numero.length < 11) {
        return `**** ${numero.slice(-4)}`;
      }

      const telefone = numero.slice(-11);

      return (
        `${telefone.slice(0, 2)} ` +
        `${telefone.slice(2, 3)}**** ` +
        `${telefone.slice(-4)}`
      );
    };

    const nomes = usuariosPagina.map(item => {
      const nomeOriginal = String(
        item.usuario.first_name || 'Sem nome'
      ).trim();

      return nomeOriginal.length > 18
        ? nomeOriginal.slice(0, 17) + '…'
        : nomeOriginal;
    });

    const larguraNome = 18;

    const linhas = usuariosPagina
      .map((item, index) => {
        const nome = nomes[index].padEnd(larguraNome, ' ');
        const telefone = mascararTelefone(
          item.usuario.user_id
        );

        return `${index + 1}. ${nome} | ${telefone}`;
      })
      .join('\n');

    const blocoLista =
      '```\n' +
      linhas +
      '\n```';

    return (
      titulo +
      `\n\nPágina ${pagina} de ${totalPaginas}` +
      `\n\n${blocoLista}` +
      (
        temMais
          ? '\n\n9. Mostrar mais usuários'
          : ''
      ) +
      '\n0. Cancelar' +
      '\n\nResponda somente com o número da opção.'
    );
  })()
}}

