    );

    const totalPaginas = Math.max(
      1,
      Math.ceil($json.usuarios_filtrados.length / porPagina)
    );

    const temMais =
      $json.usuarios_filtrados.length > inicio + porPagina;

    const acao =
      $json.usuarios_filtrados[0].acao === 'desligar'
        ? 'USUÁRIOS DISPONÍVEIS PARA DESLIGAR'
        : 'USUÁRIOS DISPONÍVEIS PARA REATIVAR';

    const mascararTelefone = valor => {
      const numero = String(valor || '').replace(/\D/g, '');

      if (numero.length < 11) {
        return `****-${numero.slice(-4)}`;
      }

      const telefoneLocal = numero.slice(-11);
      const codigoPais = numero.slice(0, -11) || '55';

      return (
        `+${codigoPais} ` +
        `(${telefoneLocal.slice(0, 2)}) ` +
        `${telefoneLocal.slice(2, 3)}****-` +
        `${telefoneLocal.slice(-4)}`
      );
    };

    const linhas = usuariosPagina
      .map(
        (item, index) =>
          `${index + 1} — *${item.usuario.first_name || 'Sem nome'}* — ` +
          mascararTelefone(item.usuario.user_id)
      )
      .join('\n');

    const navegacao = [
      temMais ? '*9* — Mostrar mais usuários' : null,
      '*0* — Cancelar'
    ]
      .filter(Boolean)
      .join('\n');

    return (
      '*VITA GESTÃO*' +
      `\n\n*${acao}*` +
      `\nPágina ${pagina} de ${totalPaginas}` +
      `\n\n${linhas}` +
      `\n\n${navegacao}` +
      '\n\nDigite o número correspondente ao usuário.'
    );
  })()
}}
